/**
 * Tech Tree Helper Functions
 *
 * Compatibility layer for migrating from old breakthroughTech system to new techTree system.
 * Provides simple API for querying tech deployment status.
 */

import { GameState } from '@/types/game';
import { getTechById } from './comprehensiveTechTree';

/**
 * Check if a technology is deployed
 *
 * @param state - Game state
 * @param techId - Technology ID from comprehensiveTechTree.ts
 * @returns Deployment level (0-1), or 0 if not deployed
 */
export function isTechDeployed(state: GameState, techId: string): number {
  const techTreeState = state.techTreeState;

  // If techTreeState not initialized, return 0
  if (!techTreeState) return 0;

  // Check if tech is unlocked
  if (!techTreeState.unlockedTech.includes(techId)) return 0;

  // Get global deployment level
  const globalDeployments = techTreeState.regionalDeployment['global'] || [];
  const deployment = globalDeployments.find((d: any) => d.techId === techId);

  return deployment ? deployment.deploymentLevel : 0;
}

/**
 * Check if a technology is unlocked (available but maybe not deployed)
 *
 * @param state - Game state
 * @param techId - Technology ID
 * @returns true if unlocked, false otherwise
 */
export function isTechUnlocked(state: GameState, techId: string): boolean {
  const techTreeState = state.techTreeState;
  if (!techTreeState) return false;

  return techTreeState.unlockedTech.includes(techId);
}

/**
 * OLD SYSTEM MAPPING TO NEW SYSTEM
 *

ocean.phytoplanktonPopulation *= (1 - ocean.pollutionLoad * 0.005);

// === WHALE PUMP (Phase 2.9+) ===
// Research: Whales cycle nutrients (iron, nitrogen, phosphorus) from depth to surface
// This fertilizes phytoplankton, enhancing ocean productivity
// Source: "The Whale Pump" (Roman et al. 2010), WDC, NOAA, WWF

const interspeciesTech = state.technologyTree?.find(t => t.id === 'interspecies_communication');
const deploymentLevel = require('./techTree/helpers').isTechDeployed(state, 'interspecies_communication');
if (interspeciesTech?.completed && deploymentLevel > 0.5) {
  // Understanding cetacean behavior → restore whale/dolphin populations → nutrient cycling

  // WHALE PUMP EFFECT: Nutrient cycling boosts phytoplankton
  // Research: Whales enhance primary productivity in regions where they occur in high densities
  // Conservative estimate: 1-2% boost at full deployment (whales restore to ~50% of pre-whaling)
  const whalePumpBoost = deploymentLevel * 0.015; // +1.5%/month at full deployment
  ocean.phytoplanktonPopulation = Math.min(1.0, ocean.phytoplanktonPopulation + whalePumpBoost);

  // FISH ABUNDANCE: "Bigger fisheries where whales are dense" (research)
  const fisheryBoost = deploymentLevel * 0.01; // +1%/month

