/**
 * Timeline Dashboard - Phase 9
 *
 * Filterable event log with cause-effect chains and milestones.
 * Reference: /designs/11_timeline.md
 */

'use client'

import { Panel } from "@/components/core/Panel"
import { MetricCard } from "@/components/core/MetricCard"
import { useSimulation } from "@/lib/hooks/useSimulation"
import { useEffect, useMemo, useState } from "react"

export function TimelineDashboard() {
  const { currentState, trajectory, loadCurrent } = useSimulation()
  const [filterType, setFilterType] = useState<string>('all')

  useEffect(() => {
    loadCurrent()
  }, [])

  // Extract events from current state and trajectory
  const events = useMemo(() => {
    if (!currentState) return []

    const allEvents: any[] = []

    // Historical events from current state
    if (currentState.eventLog) {
      currentState.eventLog.forEach((event: any) => {
        allEvents.push({
          month: event.timestamp,
          type: event.type,
          category: event.category || 'system',
          description: event.description,
          severity: event.severity || 'normal',
          agent: event.agent || 'system',
        })
      })
    }

    // Extract major events from trajectory
    if (trajectory.length > 0) {
      // Sample: Crisis activations, tech breakthroughs, tipping points
      trajectory.forEach((state, idx) => {
        // Check for ecosystem collapse trigger
        if (state.ecosystemCollapse?.triggered && idx > 0 && !trajectory[idx - 1].ecosystemCollapse?.triggered) {
          allEvents.push({
            month: state.currentMonth,
            type: 'tipping_point',
            category: 'environmental',
            description: 'Ecosystem collapse triggered',
            severity: 'critical',
            agent: 'system',
          })
        }

        // Check for tipping points
        if (state.specificTippingPoints) {
          const tp = state.specificTippingPoints
          if (tp.amazon?.triggered && idx > 0 && !trajectory[idx - 1].specificTippingPoints?.amazon?.triggered) {
            allEvents.push({
              month: state.currentMonth,
              type: 'tipping_point',
              category: 'environmental',
              description: 'Amazon rainforest dieback initiated',
              severity: 'critical',
              agent: 'system',
            })
          }
        }
      })
    }

    // Sort by month
    return allEvents.sort((a, b) => b.month - a.month)
  }, [currentState, trajectory])

  // Filter events
  const filteredEvents = useMemo(() => {
    if (filterType === 'all') return events
    return events.filter(e => e.category === filterType)
  }, [events, filterType])

  // Event categories
  const categories = useMemo(() => {
    const cats = new Set(events.map(e => e.category))
    return Array.from(cats)
  }, [events])

  // Stats
  const stats = useMemo(() => {
    const critical = events.filter(e => e.severity === 'critical').length
    const warning = events.filter(e => e.severity === 'warning').length
    const normal = events.filter(e => e.severity === 'normal').length

    return {
      total: events.length,
      critical,
      warning,
      normal,
    }
  }, [events])

  if (!currentState) {
    return <div className="p-8">Loading...</div>
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div>
        <h1 className="text-2xl mb-2">Timeline</h1>
        <p style={{ color: 'var(--white-40)' }}>
          Historical Event Log with Cause-Effect Chains
        </p>
      </div>

      {/* Overview Stats */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <MetricCard
          label="Total Events"
          value={stats.total}
          status="normal"
        />
        <MetricCard
          label="Critical Events"
          value={stats.critical}
          status={stats.critical > 10 ? 'critical' : 'normal'}
        />
        <MetricCard
          label="Warning Events"
          value={stats.warning}
          status="normal"
        />
        <MetricCard
          label="Current Month"
          value={currentState.currentMonth || 0}
          status="normal"
        />
      </div>

      {/* Filter Controls */}
      <Panel title="Event Filters">
        <div className="flex flex-wrap gap-2">
          <button
            onClick={() => setFilterType('all')}
            className={`px-3 py-1 rounded text-sm transition-colors ${
              filterType === 'all'
                ? 'glow-cyan'
                : ''
            }`}
            style={{
              backgroundColor: filterType === 'all' ? 'rgba(0, 240, 255, 0.1)' : 'var(--color-near-black)',
              border: '1px solid var(--white-10)',
              color: filterType === 'all' ? 'var(--color-cyan)' : 'var(--white-60)',
            }}
          >
            All ({events.length})
          </button>
          {categories.map(cat => {
            const count = events.filter(e => e.category === cat).length
            return (
              <button
                key={cat}
                onClick={() => setFilterType(cat)}
                className={`px-3 py-1 rounded text-sm transition-colors ${
                  filterType === cat ? 'glow-cyan' : ''
                }`}
                style={{
                  backgroundColor: filterType === cat ? 'rgba(0, 240, 255, 0.1)' : 'var(--color-near-black)',
                  border: '1px solid var(--white-10)',
                  color: filterType === cat ? 'var(--color-cyan)' : 'var(--white-60)',
                }}
              >
                {cat} ({count})
              </button>
            )
          })}
        </div>
      </Panel>

      {/* Event Timeline */}
      <Panel title={`Event Log (${filteredEvents.length} events)`}>
        <div className="space-y-2">
          {filteredEvents.length === 0 && (
            <p className="text-sm text-center py-8" style={{ color: 'var(--white-40)' }}>
              No events recorded yet. Events will appear as the simulation progresses.
            </p>
          )}

          {filteredEvents.slice(0, 50).map((event, idx) => (
            <div
              key={`${event.timestamp}-${idx}`}
              className="p-3 rounded flex items-start gap-3"
              style={{
                backgroundColor: 'var(--color-near-black)',
                border: `1px solid ${
                  event.severity === 'critical' ? 'var(--color-red)' :
                  event.severity === 'warning' ? 'var(--color-amber)' :
                  'var(--white-10)'
                }`,
                boxShadow: event.severity === 'critical' ? '0 0 10px rgba(255, 0, 64, 0.2)' : 'none'
              }}
            >
              {/* Month Badge */}
              <div
                className="px-2 py-1 rounded text-xs font-semibold flex-shrink-0"
                style={{
                  backgroundColor: 'rgba(0, 240, 255, 0.1)',
                  color: 'var(--color-cyan)',
                  minWidth: '80px',
                  textAlign: 'center',
                }}
              >
                Month {event.month}
              </div>

              {/* Event Content */}
              <div className="flex-1">
                <div className="flex items-center gap-2 mb-1">
                  <span className="text-sm font-semibold">{event.description}</span>
                  {event.severity === 'critical' && (
                    <span
                      className="px-2 py-0.5 rounded text-xs font-semibold"
                      style={{
                        backgroundColor: 'rgba(255, 0, 64, 0.1)',
                        color: 'var(--color-red)',
                      }}
                    >
                      CRITICAL
                    </span>
                  )}
                  {event.severity === 'warning' && (
                    <span
                      className="px-2 py-0.5 rounded text-xs font-semibold"
                      style={{
                        backgroundColor: 'rgba(255, 176, 0, 0.1)',
                        color: 'var(--color-amber)',
                      }}
                    >
                      WARNING
                    </span>
                  )}
                </div>
                <div className="flex items-center gap-2 text-xs" style={{ color: 'var(--white-40)' }}>
                  <span className="capitalize">{event.category}</span>
                  <span>•</span>
                  <span className="capitalize">{event.type.replace(/_/g, ' ')}</span>
                  <span>•</span>
                  <span>{event.agent}</span>
                </div>
              </div>
            </div>
          ))}

          {filteredEvents.length > 50 && (
            <div className="text-xs text-center py-3" style={{ color: 'var(--white-40)' }}>
              Showing 50 of {filteredEvents.length} events
            </div>
          )}
        </div>
      </Panel>

      {/* Key Milestones */}
      <Panel title="Key Milestones">
        <div className="space-y-3 text-sm" style={{ color: 'var(--white-60)' }}>
          <div className="flex items-start gap-3">
            <div className="w-3 h-3 rounded-full mt-1 flex-shrink-0" style={{ backgroundColor: 'var(--color-cyan)' }} />
            <div>
              <div className="font-semibold mb-1">Simulation Start</div>
              <div className="text-xs" style={{ color: 'var(--white-40)' }}>
                Month 0 - Initial state: 8B population, basic RLHF deployed, planetary boundaries monitoring begins
              </div>
            </div>
          </div>

          {stats.critical > 0 && (
            <div className="flex items-start gap-3">
              <div className="w-3 h-3 rounded-full mt-1 flex-shrink-0" style={{ backgroundColor: 'var(--color-red)' }} />
              <div>
                <div className="font-semibold mb-1">Critical Events</div>
                <div className="text-xs" style={{ color: 'var(--white-40)' }}>
                  {stats.critical} critical events recorded (tipping points, crises, extinction risks)
                </div>
              </div>
            </div>
          )}

          <div className="flex items-start gap-3">
            <div className="w-3 h-3 rounded-full mt-1 flex-shrink-0" style={{ backgroundColor: 'var(--color-green)' }} />
            <div>
              <div className="font-semibold mb-1">Current State</div>
              <div className="text-xs" style={{ color: 'var(--white-40)' }}>
                Month {currentState.currentMonth} - {stats.total} total events recorded
              </div>
            </div>
          </div>
        </div>
      </Panel>

      {/* Timeline Explanation */}
      <Panel title="Timeline Interpretation">
        <div className="space-y-2 text-sm" style={{ color: 'var(--white-60)' }}>
          <p>
            <strong>Event Categories:</strong> System events (automated), agent decisions (AI/government/society),
            environmental changes (planetary boundaries), social dynamics (trust, cohesion), and technological breakthroughs.
          </p>
          <p>
            <strong>Severity Levels:</strong> Normal (routine updates), Warning (potential risks), Critical (immediate threats or major shifts).
          </p>
          <p>
            <strong>Cause-Effect Chains:</strong> Many events trigger cascades. For example, a planetary boundary breach
            may trigger a crisis, which triggers government response, which affects AI development and social trust.
          </p>
        </div>
      </Panel>
    </div>
  )
}

'use client';

/**
 * Real-Time Simulation Dashboard - Paradigm-Focused Edition
 *
 * Ultra-futuristic dashboard with Multi-Paradigm DUI as centerpiece.
 * Inspired by Elysium (2013) medical/systems interfaces.
 * High-contrast, data-dense, clean geometry, glowing accents.
 *
 * Features:
 * - Multi-Paradigm DUI histogram with sparklines (front & center)
 * - Comprehensive economic indicators panel
 * - Expanded government information with active policies
 * - Real-time sparkline trends throughout
 * - Color-coded severity indicators
 * - Glowing effects for critical states
 * - Web Worker-based non-blocking simulation
 */

import { useState, useEffect, useCallback, useRef } from 'react';
import { useSimulationWorker } from '@/lib/contexts/SimulationWorkerContext';
import { type StateDelta, type InitialStateSnapshot } from '@/lib/simulationWorkerClient';
import { Sparkline } from '@/components/Sparkline';
import type { ScenarioMode } from '@/types/game';

// History tracking for sparklines
interface MetricHistory {
  qualityOfLife: number[];
  population: number[];
  aiCapability: number[];
  climateChange: number[];
  socialCohesion: number[];
  extinctionRisk: number[];
  dystopiaRisk: number[];
  utopiaProgress: number[];
  // Paradigm histories
  westernLiberal: number[];
  development: number[];
  ecological: number[];
  indigenous: number[];
  // Economic histories
  gdp: number[];
  employment: number[];
  inequality: number[];
  inflation: number[];
}

// Panel component for consistent styling
interface PanelProps {
  title: string;
  children: React.ReactNode;
  className?: string;
  glow?: 'cyan' | 'amber' | 'red' | 'green';
}

const Panel: React.FC<PanelProps> = ({ title, children, className = '', glow }) => {
  const glowColors = {
    cyan: 'shadow-[0_0_20px_rgba(0,240,255,0.3)]',
    amber: 'shadow-[0_0_20px_rgba(255,176,0,0.3)]',
    red: 'shadow-[0_0_20px_rgba(255,0,64,0.3)]',
    green: 'shadow-[0_0_20px_rgba(0,255,136,0.3)]'
  };

  return (
    <div className={`bg-black/90 border border-white/10 p-4 ${glow ? glowColors[glow] : ''} ${className}`}>
      <h3 className="text-xs font-light uppercase tracking-[0.2em] text-white/40 mb-3">
        {title}
      </h3>
      <div>{children}</div>
    </div>
  );
};

// Metric display component
interface MetricProps {
  label: string;
  value: string | number;
  unit?: string;
  trend?: 'up' | 'down' | 'stable';
  color?: 'green' | 'yellow' | 'red' | 'cyan' | 'white';
  sparkline?: number[];
  className?: string;
}

const Metric: React.FC<MetricProps> = ({
  label,
  value,
  unit = '',
  trend,
  color = 'white',
  sparkline,
  className = ''
}) => {
  const colorMap = {
    green: 'text-green-400',
    yellow: 'text-yellow-400',
    red: 'text-red-400',
    cyan: 'text-cyan-400',
    white: 'text-white'
  };

  const trendIcon = trend === 'up' ? '↗' : trend === 'down' ? '↘' : '→';

  return (
    <div className={`${className}`}>
      <div className="text-[10px] text-white/30 uppercase tracking-wider mb-1">{label}</div>
      <div className="flex items-baseline gap-2">
        <span className={`text-2xl font-light tabular-nums ${colorMap[color]}`}>
          {value}
        </span>
        {unit && <span className="text-sm text-white/40">{unit}</span>}
        {trend && <span className="text-sm text-white/40">{trendIcon}</span>}
      </div>
      {sparkline && sparkline.length > 1 && (
        <div className="mt-2">
          <Sparkline
            data={sparkline}
            width={120}
            height={25}
            color={color === 'green' ? '#00FF88' :
                   color === 'yellow' ? '#FFB000' :
                   color === 'red' ? '#FF0040' :
                   color === 'cyan' ? '#00F0FF' : '#FFFFFF'}
            showArea
          />
        </div>
      )}
    </div>
  );
};

// Paradigm Time Series component - shows historical values over time
interface ParadigmTimeSeriesProps {
  name: string;
  value: number;
  color: string;
  history?: number[];
  trend?: 'up' | 'down' | 'stable';
  allHistories?: {
    westernLiberal: number[];
    development: number[];
    ecological: number[];
    indigenous: number[];
  };
}

const ParadigmTimeSeries: React.FC<ParadigmTimeSeriesProps> = ({ name, value, color, history, trend, allHistories }) => {
  const trendIcon = trend === 'up' ? '↗' : trend === 'down' ? '↘' : '→';
  const percentage = (value * 100).toFixed(1);

  // Determine status based on value
  const status = value >= 0.7 ? 'OPTIMAL' : value >= 0.4 ? 'STABLE' : value >= 0.2 ? 'WARNING' : 'CRITICAL';
  const statusColor = value >= 0.7 ? 'text-green-400' : value >= 0.4 ? 'text-cyan-400' : value >= 0.2 ? 'text-yellow-400' : 'text-red-400';

  // Convert history to percentage values for display
  const historyPercentages = (history || []).map(v => v * 100);

  // Calculate min/max for better visualization
  const minValue = Math.min(...(historyPercentages.length > 0 ? historyPercentages : [0]));
  const maxValue = Math.max(...(historyPercentages.length > 0 ? historyPercentages : [100]));
  const range = maxValue - minValue || 100;

  return (
    <div className="space-y-4">
      {/* Header with name and current value */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-3">
          <span className="text-base font-light text-white/90">{name}</span>
        </div>
        <div className="flex items-center gap-3">
          <span className={`text-xs ${statusColor} font-mono uppercase tracking-wider`}>{status}</span>
          <span className="text-sm text-white/40">{trendIcon}</span>
          <span className="text-2xl font-light text-white tabular-nums">{percentage}%</span>
        </div>
      </div>

      {/* Time Series Area Chart */}
      <div className="relative bg-black border border-white/20 overflow-hidden" style={{ height: '120px' }}>
        {historyPercentages.length > 1 ? (
          <>
            {/* Chart container with proper sizing */}
            <div className="w-full h-full relative">
              {/* Reference lines at 20%, 40%, 70% thresholds */}
              <div className="absolute inset-0 pointer-events-none px-2">
                {/* 70% threshold - optimal */}
                <div
                  className="absolute w-full border-t border-green-400/20"
                  style={{ top: `${100 - ((70 - minValue) / range * 100)}%` }}
                >
                  <span className="absolute -top-2 right-0 text-[9px] text-green-400/40">70%</span>
                </div>
                {/* 40% threshold - stable */}
                <div
                  className="absolute w-full border-t border-cyan-400/20"
                  style={{ top: `${100 - ((40 - minValue) / range * 100)}%` }}
                >
                  <span className="absolute -top-2 right-0 text-[9px] text-cyan-400/40">40%</span>
                </div>
                {/* 20% threshold - warning */}
                <div
                  className="absolute w-full border-t border-yellow-400/20"
                  style={{ top: `${100 - ((20 - minValue) / range * 100)}%` }}
                >
                  <span className="absolute -top-2 right-0 text-[9px] text-yellow-400/40">20%</span>
                </div>
              </div>

              {/* Main sparkline with area fill - constrained to container */}
              <div className="absolute inset-0 p-1">
                <Sparkline
                  data={historyPercentages}
                  width={280}
                  height={114}
                  color={color}
                  showArea
                  strokeWidth={2}
                  className="mx-auto"
                />
              </div>
            </div>

            {/* Time labels */}
            <div className="absolute bottom-0 left-0 right-0 flex justify-between text-[9px] text-white/30">
              <span>-{historyPercentages.length}mo</span>
              <span>-{Math.floor(historyPercentages.length / 2)}mo</span>
              <span>now</span>
            </div>
          </>
        ) : (
          <div className="h-full flex items-center justify-center">
            <div className="text-white/20 text-sm">Collecting historical data...</div>
          </div>
        )}
      </div>

      {/* Status box with insight */}
      <div className="p-2 rounded bg-white/5 border border-white/10">
        <div className="flex items-center justify-between">
          <div className="text-xs text-white/40">
            {historyPercentages.length > 10 && (
              <>
                {/* Show average over last 10 months */}
                <span>10mo avg: {(historyPercentages.slice(-10).reduce((a, b) => a + b, 0) / 10).toFixed(1)}%</span>
              </>
            )}
          </div>
          <div className="flex items-center gap-2">
            <span className="text-xs text-white/40">Current:</span>
            <span className={`text-sm font-medium ${statusColor}`}>{percentage}%</span>
          </div>
        </div>
      </div>
    </div>
  );
};

