cat > /tmp/fix_gov_events.awk << 'EOF'
BEGIN { in_event = 0; event_line = 0; }

/events: \[{$/ {
    in_event = 1;
    event_line = NR;
    print;
    next;
}

in_event == 1 && /^[ \t]+type:/ {
    # Get indentation
    match($0, /^[ \t]+/);
    indent = substr($0, RSTART, RLENGTH);

    # Extract event type
    match($0, /'([^']+)'/, arr);
    event_type = arr[1];

    # Print id line before type
    print indent "id: `" event_type "_${state.currentMonth}_${Math.random().toString(36).substr(2, 9)}`,";
    print;
    in_event = 2;
    next;
}

in_event == 2 && /^[ \t]+timestamp:/ {
    print;
    # Get indentation
    match($0, /^[ \t]+/);
    indent = substr($0, RSTART, RLENGTH);
    # Add severity and agent
    print indent "severity: 'info',";
    print indent "agent: 'government',";
    in_event = 0;
    next;
}

{ print }
EOF

